arguments.file_text:
namespace sv_b2c3fbd61b3e4b309cfa788d2fda7e95.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@rendermode InteractiveServer
@using sv_b2c3fbd61b3e4b309cfa788d2fda7e95.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar">
        <h5 class="sidebar-title">Settings</h5>
        <ul class="nav flex-column">
            @foreach (var section in _sections)
            {
                <li class="nav-item">
                    <button class="nav-link @(section == _activeSection ? "active" : "")"
                            @onclick="() => SetActiveSection(section)">
                        <span class="section-icon">@GetSectionIcon(section)</span>
                        @section
                    </button>
                </li>
            }
        </ul>
    </nav>

    <div class="settings-content">
        @if (_loading)
        {
            <div class="d-flex justify-content-center p-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @if (_toastMessage is not null)
            {
                <div class="alert @(_toastIsError ? "alert-danger" : "alert-success") alert-dismissible fade show toast-message" role="alert">
                    @_toastMessage
                    <button type="button" class="btn-close" @onclick="DismissToast"></button>
                </div>
            }

            @switch (_activeSection)
            {
                case "Profile":
                    @RenderProfileSection()
                    break;
                case "Notifications":
                    @RenderNotificationsSection()
                    break;
                case "Security":
                    @RenderSecuritySection()
                    break;
                case "Appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }
    </div>
</div>

@* ── Confirmation Dialog ── *@
@if (_showConfirmDialog)
{
    <div class="modal-backdrop fade show"></div>
    <div class="modal fade show d-block" tabindex="-1" role="dialog">
        <div class="modal-dialog modal-dialog-centered" role="document">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">@_confirmTitle</h5>
                    <button type="button" class="btn-close" @onclick="CancelConfirm"></button>
                </div>
                <div class="modal-body">
                    <p>@_confirmMessage</p>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="CancelConfirm">Cancel</button>
                    <button class="btn btn-danger" @onclick="ConfirmAction">Confirm</button>
                </div>
            </div>
        </div>
    </div>
}

@* ────────────────────────── Profile Section ────────────────────────── *@

@{
    RenderFragment RenderProfileSection() =>
        @<section>
            <h3>Profile</h3>
            <hr />

            <div class="row mb-4">
                <div class="col-md-8">
                    <div class="mb-3">
                        <label class="form-label">Display Name</label>
                        <input type="text" class="form-control" @bind="_editDisplayName" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Email</label>
                        <input type="email" class="form-control" @bind="_editEmail" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Bio</label>
                        <textarea class="form-control" rows="4" @bind="_editBio"></textarea>
                    </div>
                </div>
                <div class="col-md-4">
                    <div class="avatar-preview">
                        <label class="form-label">Avatar Preview</label>
                        <div class="avatar-frame mb-2">
                            @if (!string.IsNullOrWhiteSpace(_editAvatarUrl))
                            {
                                <img src="@_editAvatarUrl" alt="Avatar" class="avatar-img" />
                            }
                            else
                            {
                                <div class="avatar-placeholder">No Avatar</div>
                            }
                        </div>
                        <label class="form-label">Avatar URL</label>
                        <input type="url" class="form-control form-control-sm" @bind="_editAvatarUrl" />
                    </div>
                </div>
            </div>

            <div class="d-flex gap-2">
                <button class="btn btn-primary" @onclick="SaveProfile" disabled="@_saving">
                    @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Save Changes
                </button>
                <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>;
}

@* ────────────────────── Notifications Section ────────────────────── *@

@{
    RenderFragment RenderNotificationsSection() =>
        @<section>
            <h3>Notifications</h3>
            <hr />

            <div class="mb-4">
                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_editEmailNotifications" />
                    <label class="form-check-label" for="emailNotif">Email Notifications</label>
                </div>
                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_editPushNotifications" />
                    <label class="form-check-label" for="pushNotif">Push Notifications</label>
                </div>
                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_editWeeklyDigest" />
                    <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
                </div>
            </div>

            <h5>Muted Channels</h5>
            @if (_allChannels.Count == 0)
            {
                <p class="text-muted">No channels available.</p>
            }
            else
            {
                <div class="channel-list mb-4">
                    @foreach (var channel in _allChannels)
                    {
                        var isMuted = _editMutedChannels.Contains(channel);
                        <div class="form-check mb-2">
                            <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                                   checked="@isMuted"
                                   @onchange="e => ToggleMuteChannel(channel, (bool)(e.Value ?? false))" />
                            <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
                        </div>
                    }
                </div>
            }

            <button class="btn btn-primary" @onclick="SaveNotifications" disabled="@_saving">
                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save Preferences
            </button>
        </section>;
}

@* ────────────────────────── Security Section ────────────────────────── *@

@{
    RenderFragment RenderSecuritySection() =>
        @<section>
            <h3>Security</h3>
            <hr />

            @* Change Password *@
            <div class="card mb-4">
                <div class="card-header d-flex justify-content-between align-items-center"
                     style="cursor:pointer" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span>Change Password</span>
                    <span>@(_passwordPanelOpen ? "▲" : "▼")</span>
                </div>
                @if (_passwordPanelOpen)
                {
                    <div class="card-body">
                        <div class="mb-3">
                            <label class="form-label">Current Password</label>
                            <input type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">New Password</label>
                            <input type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Confirm New Password</label>
                            <input type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-primary" @onclick="ChangePassword" disabled="@_saving">
                            @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                            Update Password
                        </button>
                    </div>
                }
            </div>

            @* Two-Factor Authentication *@
            <div class="card mb-4">
                <div class="card-body d-flex justify-content-between align-items-center">
                    <div>
                        <h6 class="mb-1">Two-Factor Authentication</h6>
                        <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                            @(_twoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" @bind="_twoFactorEnabled" />
                    </div>
                </div>
            </div>

            @* Active Sessions *@
            <h5>Active Sessions</h5>
            @if (_sessions.Count == 0)
            {
                <p class="text-muted">No active sessions.</p>
            }
            else
            {
                <div class="table-responsive">
                    <table class="table table-striped align-middle">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@session.LastActive.ToString("g")</td>
                                    <td>
                                        @if (session != _sessions.FirstOrDefault())
                                        {
                                            <button class="btn btn-sm btn-outline-danger"
                                                    @onclick="() => RequestRevokeSession(session)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="badge bg-info">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
        </section>;
}

@* ────────────────────── Appearance Section ────────────────────── *@

@{
    RenderFragment RenderAppearanceSection() =>
        @<section>
            <h3>Appearance</h3>
            <hr />

            <div class="row">
                <div class="col-md-6">
                    @* Theme *@
                    <div class="mb-4">
                        <h6>Theme</h6>
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="@($"theme-{theme}")" value="@theme"
                                       checked="@(_editTheme == theme)"
                                       @onchange="() => _editTheme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                            </div>
                        }
                    </div>

                    @* Font Size *@
                    <div class="mb-4">
                        <h6>Font Size</h6>
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="@($"fs-{size}")" value="@size"
                                       checked="@(_editFontSize == size)"
                                       @onchange="() => _editFontSize = size" />
                                <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                            </div>
                        }
                    </div>

                    @* Language *@
                    <div class="mb-4">
                        <h6>Language</h6>
                        <select class="form-select" @bind="_editLanguage">
                            <option value="en">English</option>
                            <option value="es">Español</option>
                            <option value="fr">Français</option>
                            <option value="de">Deutsch</option>
                            <option value="ja">日本語</option>
                            <option value="zh">中文</option>
                        </select>
                    </div>

                    @* Compact Mode *@
                    <div class="mb-4">
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" id="compactMode" @bind="_editCompactMode" />
                            <label class="form-check-label" for="compactMode">Compact Mode</label>
                        </div>
                    </div>

                    <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_saving">
                        @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                        Save
                    </button>
                </div>

                @* Live Preview *@
                <div class="col-md-6">
                    <h6>Preview</h6>
                    <div class="live-preview @GetPreviewClasses()">
                        <div class="preview-header">
                            <strong>Sample Header</strong>
                        </div>
                        <div class="preview-body">
                            <p>This is a preview of your selected appearance settings.</p>
                            <button class="btn btn-sm @(_editTheme == "Dark" ? "btn-light" : "btn-primary")">
                                Sample Button
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </section>;
}

@code {
    private readonly string[] _sections = ["Profile", "Notifications", "Security", "Appearance"];
    private string _activeSection = "Profile";
    private bool _loading = true;
    private bool _saving;

    // Toast
    private string? _toastMessage;
    private bool _toastIsError;
    private CancellationTokenSource? _toastCts;

    // Confirm dialog
    private bool _showConfirmDialog;
    private string _confirmTitle = "";
    private string _confirmMessage = "";
    private Func<Task>? _confirmCallback;

    // ── Profile state ──
    private UserProfile? _savedProfile;
    private string _editDisplayName = "";
    private string _editEmail = "";
    private string _editAvatarUrl = "";
    private string _editBio = "";

    // ── Notification state ──
    private NotificationPrefs? _savedNotifPrefs;
    private bool _editEmailNotifications;
    private bool _editPushNotifications;
    private bool _editWeeklyDigest;
    private List<string> _editMutedChannels = [];
    private readonly List<string> _allChannels = ["general", "announcements", "random", "engineering", "design", "marketing"];

    // ── Security state ──
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _twoFactorEnabled;
    private List<ActiveSession> _sessions = [];

    // ── Appearance state ──
    private AppearanceSettings? _savedAppearance;
    private string _editTheme = "Light";
    private string _editFontSize = "Medium";
    private string _editLanguage = "en";
    private bool _editCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData(_activeSection);
        _loading = false;
    }

    private async Task SetActiveSection(string section)
    {
        if (section == _activeSection) return;
        _activeSection = section;
        _loading = true;
        DismissToast();
        await LoadSectionData(section);
        _loading = false;
    }

    private async Task LoadSectionData(string section)
    {
        switch (section)
        {
            case "Profile":
                _savedProfile = await SettingsService.GetProfileAsync();
                ApplyProfile(_savedProfile);
                break;
            case "Notifications":
                _savedNotifPrefs = await SettingsService.GetNotificationPrefsAsync();
                ApplyNotifPrefs(_savedNotifPrefs);
                break;
            case "Security":
                var sec = await SettingsService.GetSecuritySettingsAsync();
                _twoFactorEnabled = sec.TwoFactorEnabled;
                _sessions = sec.Sessions.ToList();
                _currentPassword = "";
                _newPassword = "";
                _confirmPassword = "";
                break;
            case "Appearance":
                _savedAppearance = await SettingsService.GetAppearanceAsync();
                ApplyAppearance(_savedAppearance);
                break;
        }
    }

    // ── Profile ──

    private void ApplyProfile(UserProfile p)
    {
        _editDisplayName = p.DisplayName;
        _editEmail = p.Email;
        _editAvatarUrl = p.AvatarUrl;
        _editBio = p.Bio;
    }

    private async Task SaveProfile()
    {
        _saving = true;
        try
        {
            var profile = new UserProfile(_editDisplayName, _editEmail, _editAvatarUrl, _editBio);
            await SettingsService.SaveProfileAsync(profile);
            _savedProfile = profile;
            ShowToast("Profile saved successfully.");
        }
        catch (Exception ex)
        {
            ShowToast($"Failed to save profile: {ex.Message}", isError: true);
        }
        finally { _saving = false; }
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
            ApplyProfile(_savedProfile);
    }

    // ── Notifications ──

    private void ApplyNotifPrefs(NotificationPrefs p)
    {
        _editEmailNotifications = p.EmailNotifications;
        _editPushNotifications = p.PushNotifications;
        _editWeeklyDigest = p.WeeklyDigest;
        _editMutedChannels = p.MutedChannels.ToList();
    }

    private void ToggleMuteChannel(string channel, bool muted)
    {
        if (muted && !_editMutedChannels.Contains(channel))
            _editMutedChannels.Add(channel);
        else if (!muted)
            _editMutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        _saving = true;
        try
        {
            var prefs = new NotificationPrefs(_editEmailNotifications, _editPushNotifications, _editWeeklyDigest, _editMutedChannels.ToList());
            await SettingsService.SaveNotificationPrefsAsync(prefs);
            _savedNotifPrefs = prefs;
            ShowToast("Notification preferences saved.");
        }
        catch (Exception ex)
        {
            ShowToast($"Failed to save preferences: {ex.Message}", isError: true);
        }
        finally { _saving = false; }
    }

    // ── Security ──

    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_newPassword) || _newPassword != _confirmPassword)
        {
            ShowToast("Passwords do not match or are empty.", isError: true);
            return;
        }
        _saving = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
            _passwordPanelOpen = false;
            ShowToast("Password updated successfully.");
        }
        catch (Exception ex)
        {
            ShowToast($"Failed to change password: {ex.Message}", isError: true);
        }
        finally { _saving = false; }
    }

    private void RequestRevokeSession(ActiveSession session)
    {
        _confirmTitle = "Revoke Session";
        _confirmMessage = $"Are you sure you want to revoke the session on \"{session.Device}\" in {session.Location}?";
        _confirmCallback = async () =>
        {
            await SettingsService.RevokeSessionAsync(session.Id);
            _sessions.Remove(session);
            ShowToast("Session revoked.");
        };
        _showConfirmDialog = true;
    }

    private async Task ConfirmAction()
    {
        _showConfirmDialog = false;
        if (_confirmCallback is not null)
        {
            try
            {
                await _confirmCallback();
            }
            catch (Exception ex)
            {
                ShowToast($"Action failed: {ex.Message}", isError: true);
            }
        }
    }

    private void CancelConfirm() => _showConfirmDialog = false;

    // ── Appearance ──

    private void ApplyAppearance(AppearanceSettings a)
    {
        _editTheme = a.Theme;
        _editFontSize = a.FontSize;
        _editLanguage = a.Language;
        _editCompactMode = a.CompactMode;
    }

    private async Task SaveAppearance()
    {
        _saving = true;
        try
        {
            var settings = new AppearanceSettings(_editTheme, _editFontSize, _editLanguage, _editCompactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            _savedAppearance = settings;
            ShowToast("Appearance settings saved.");
        }
        catch (Exception ex)
        {
            ShowToast($"Failed to save appearance: {ex.Message}", isError: true);
        }
        finally { _saving = false; }
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add(_editTheme switch { "Dark" => "preview-dark", "Light" => "preview-light", _ => "preview-system" });
        classes.Add(_editFontSize switch { "Small" => "preview-font-sm", "Large" => "preview-font-lg", _ => "preview-font-md" });
        if (_editCompactMode) classes.Add("preview-compact");
        return string.Join(' ', classes);
    }

    // ── Helpers ──

    private static string GetSectionIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };

    private void ShowToast(string message, bool isError = false)
    {
        _toastCts?.Cancel();
        _toastMessage = message;
        _toastIsError = isError;

        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;
        _ = Task.Run(async () =>
        {
            await Task.Delay(4000, token);
            if (!token.IsCancellationRequested)
            {
                await InvokeAsync(() =>
                {
                    _toastMessage = null;
                    StateHasChanged();
                });
            }
        }, token);
    }

    private void DismissToast()
    {
        _toastCts?.Cancel();
        _toastMessage = null;
    }
}

/* ── Layout ── */
.settings-dashboard {
    display: flex;
    min-height: 70vh;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    background: #fff;
}

.settings-sidebar {
    width: 220px;
    min-width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1rem 0;
}

.sidebar-title {
    padding: 0 1rem 0.75rem;
    margin: 0;
    font-weight: 600;
    color: #495057;
}

.settings-sidebar .nav-link {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.6rem 1.25rem;
    color: #495057;
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    font-size: 0.95rem;
    border-left: 3px solid transparent;
    transition: background 0.15s, border-color 0.15s;
}

.settings-sidebar .nav-link:hover {
    background: #e9ecef;
}

.settings-sidebar .nav-link.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

.section-icon {
    font-size: 1.1rem;
}

.settings-content {
    flex: 1;
    padding: 1.5rem 2rem;
    position: relative;
}

/* ── Toast ── */
.toast-message {
    position: sticky;
    top: 0;
    z-index: 10;
}

/* ── Avatar ── */
.avatar-preview {
    text-align: center;
}

.avatar-frame {
    width: 120px;
    height: 120px;
    margin: 0 auto;
    border-radius: 50%;
    overflow: hidden;
    border: 3px solid #dee2e6;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #f8f9fa;
}

.avatar-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    color: #adb5bd;
    font-size: 0.85rem;
}

/* ── Channel list ── */
.channel-list {
    max-height: 220px;
    overflow-y: auto;
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    padding: 0.75rem;
}

/* ── Live Preview ── */
.live-preview {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    transition: all 0.2s ease;
}

.preview-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #dee2e6;
}

.preview-body {
    padding: 1rem;
}

/* Theme variants */
.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-light .preview-header {
    background: #f8f9fa;
}

.preview-dark {
    background: #212529;
    color: #f8f9fa;
}

.preview-dark .preview-header {
    background: #343a40;
    border-color: #495057;
}

.preview-dark .preview-body {
